test('invoiceTotals returns subtotal, discount, vat, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // DES-HOUR: 2 * 8500 = 17000
  // Discount: 17000 * 10% = 1700
  // Amount after discount: 17000 - 1700 = 15300
  // VAT: 15300 * 21% = 3213
  // Total: 17000 - 1700 + 3213 = 18513
  assert.equal(r.value.subtotal, 17000);
  assert.equal(r.value.discount, 1700);
  assert.equal(r.value.vat, 3213);
  assert.equal(r.value.total, 18513);
});

