    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // DES-HOUR: 17000
  // Discount: 0 (no tier discount)
  // VAT: 17000 * 21% = 3570
  // Total: 17000 + 3570 = 20570
  assert.equal(r.value.subtotal, 17000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 3570);
  assert.equal(r.value.total, 20570);
});

test('invoiceTotals mixes tier discounts with explicit discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 }, // gets 5% from tier
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 15 }, // explicit 15%
    ],
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // DES-HOUR: 8500, discount: 425 (5%), amount after: 8075, VAT: 1696
  // DEV-HOUR: 9500, discount: 1425 (15%), amount after: 8075, VAT: 1696
  // Subtotal: 18000, Discount: 1850, VAT: 3392, Total: 19542
  assert.equal(r.value.subtotal, 18000);
  assert.equal(r.value.discount, 1850);
  assert.equal(r.value.vat, 3392);
  assert.equal(r.value.total, 19542);
});

test('invoiceTotals calculates VAT on single line at 21%', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // DES-HOUR: 8500 cents (no discount)
  // VAT: 8500 * 21% = 1785 cents
  // Total: 8500 + 1785 = 10285
  assert.equal(r.value.subtotal, 8500);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 1785);
  assert.equal(r.value.total, 10285);
});

test('invoiceTotals calculates VAT on multiple lines with different rates', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 1 }, // 9% VAT
    ],
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // DES-HOUR: 8500, VAT: 8500 * 21% = 1785
  // PRINT-A4: 37, VAT: 37 * 9% = 3 (rounded)
  // Subtotal: 8537, Discount: 0, VAT: 1788, Total: 10325
  assert.equal(r.value.subtotal, 8537);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 1788);
  assert.equal(r.value.total, 10325);
});

test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ qty: 1, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Line: 8500
  // Discount: 8500 * 10% = 850
  // Amount after discount: 8500 - 850 = 7650
  // VAT: 7650 * 21% = 1606.5 -> 1606 (banker's rounding, 1606 is even)
  // Total: 8500 - 850 + 1606 = 9256
  assert.equal(r.value.subtotal, 8500);
  assert.equal(r.value.discount, 850);
  assert.equal(r.value.vat, 1606);
  assert.equal(r.value.total, 9256);
});

test('invoiceTotals handles VAT-exempt products (0% VAT rate)', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }], // VAT exempt
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // WORKSHOP-DAY: 60000, VAT rate 0%
  // VAT: 0
  // Total: 60000 + 0 = 60000
  assert.equal(r.value.subtotal, 60000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.total, 60000);
});

